        if "*" in ctx["question"]:
            answer = final_answer(output)
            if answer is None:
                return True
            # Extract numbers from output and check for logical consistency
            numbers = [float(num) for num in re.findall(r"\b\d+\.?\d*\b", output)]
            if len(numbers) >= 2:
                product = numbers[0] * numbers[1]
